from catena.strings import (
    safe_int_str,
    safe_full_int_str,
)

from testing.bigints import load, build_store_path


def test_safe_int_str():
    """Test the safe_int_str function with various inputs."""
    assert isinstance(safe_int_str(123), str)
    assert safe_int_str(123) == "123"
    assert safe_int_str(-456) == "-456"
    assert safe_int_str(0) == "0"
    assert safe_int_str(10**98 - 1) == str(10**98 - 1)
    n = 10**99 - 1
    assert safe_int_str(n) == f"BigBigInt(sign=1, digits=100, tail(99)={"9" * 99}, hash={hash(n)})"


def test__safe_int_str_with_very_large_integer():
    """Test that safe_int_str does not raise an exception for a very large integer."""
    random_10000d = load(build_store_path('random_strings'))['random_10000d']
    try:
        result = safe_int_str(random_10000d)
    except Exception as e:
        assert False, f"safe_int_str raised an exception for a very large integer: {e}"

    assert isinstance(result, str)

    # Same tail and digits, but different hash due to different integer value.
    shifted_random_10000d = random_10000d + 10**150
    try:
        shifted_result = safe_int_str(shifted_random_10000d)
    except Exception as e:
        assert False, f"safe_int_str raised an exception for a very large integer: {e}"

    assert isinstance(shifted_result, str)
    assert shifted_result != result
    assert result.split('hash=')[0] == shifted_result.split('hash=')[0]


def test_safe_full_int_str():
    """Test the safe_full_int_str function with various inputs."""
    assert isinstance(safe_full_int_str(123), str)
    assert safe_full_int_str(123) == "123"
    assert safe_full_int_str(-456) == "-456"
    assert safe_full_int_str(0) == "0"
    assert safe_full_int_str(10**98 - 1) == str(10**98 - 1)
    assert safe_full_int_str(10**99 - 1) == str(10**99 - 1)
    assert safe_full_int_str(10**100 - 1) == str(10**100 - 1)

    try:
        big_num_str = safe_full_int_str(10**5001)
    except Exception as e:
        assert False, f"safe_full_int_str raised an exception for a very large integer: {e}"

    assert big_num_str == "1" + "0" * 5001
    assert isinstance(big_num_str, str)

    big_101 = load()['big_101']
    assert safe_full_int_str(big_101) == ''


def test_safe_full_int_str_against_safe_int_str():
    """Test that safe_full_int_str produces the same results as safe_int_str for small integers."""
    test_cases = [0, 1, -1, 123, -456, 10**98 - 1, -(10**98 - 1)]
    
    for n in test_cases:
        assert safe_full_int_str(n) == safe_int_str(n)